command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/public-source-delivery-policy-20261006"
$expectedWork="e495b29c89fa538363ecd8bbea9a788c81ca743e"
$expectedMain="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$source="bc63c8b48e466d1275cc6dcffb0c50e02d39db60"
$temp=Join-Path $env:RUNNER_TEMP ("public-source-final-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --tags --prune
  if($LASTEXITCODE -ne 0){throw "final fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $workRef="refs/remotes/origin/"+$branch
  $workSha=(& git rev-parse $workRef).Trim()
  if($mainSha -ne $expectedMain){throw "main moved before cleanup: $mainSha"}
  if($workSha -ne $expectedWork){throw "work branch moved before cleanup: $workSha"}

  $mainTree=(& git rev-parse "refs/remotes/origin/main^{tree}").Trim()
  $workTree=(& git rev-parse ($workRef+"^{tree}")).Trim()
  if($mainTree -ne $workTree){throw "merged main tree differs from work branch tree"}

  & git merge-base --is-ancestor $source refs/remotes/origin/main
  if($LASTEXITCODE -ne 0){throw "binary source revision is not preserved in main history"}

  & git show-ref --verify --quiet refs/tags/v1.0.0.0
  if($LASTEXITCODE -eq 0){throw "reserved v1.0.0.0 tag was unexpectedly pre-created"}
  $global:LASTEXITCODE=0

  $immutable=& gh api repos/tngkrwlsmd/flyExplorer/immutable-releases
  if($LASTEXITCODE -ne 0){throw "immutable release status query failed"}
  $immutableObject=$immutable | ConvertFrom-Json
  if(-not $immutableObject.enabled){throw "immutable releases are disabled"}

  & git worktree add --detach $temp $expectedMain
  if($LASTEXITCODE -ne 0){throw "main policy worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  & python -X utf8 packaging\public_source_delivery.py --phase prepublish
  if($LASTEXITCODE -ne 0){throw "merged main public-source policy check failed"}

  Set-Location -LiteralPath $repo
  & git worktree remove --force $temp
  if($LASTEXITCODE -ne 0){throw "main policy worktree cleanup failed"}
  $worktreeAdded=$false
  & git worktree prune

  & git push origin --delete $branch
  if($LASTEXITCODE -ne 0){throw "failed to delete merged public-source work branch"}
  & git fetch origin --prune --no-tags
  if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
  if(& git show-ref --verify --quiet $workRef){throw "public-source work branch still exists"}

  Write-Host "FINAL_MAIN="+$expectedMain
  Write-Host "FINAL_BINARY_SOURCE_ANCESTOR="+$source
  Write-Host "FINAL_RESERVED_TAG=v1.0.0.0"
  Write-Host "FINAL_RESERVED_TAG_PRECREATED=false"
  Write-Host "FINAL_IMMUTABLE_RELEASES_ENABLED=true"
  Write-Host "PUBLIC_SOURCE_POLICY_MERGE_CLEANUP=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
